# =============================================================================
# Chapter 2 figures: From Research Questions to Formal Hypotheses
#
# Run from the project root:
#   Rscript r_code/figures/chapter_02.R
#
# Figure 2.1 is a conceptual diagram, not a data plot. It contrasts an
# observational study with a randomized experiment. Captions and alt text live
# here, next to the code. figures/chapter_02/figures.yml is generated by
# save_book_fig(); do not edit it by hand.
# =============================================================================

source("r_code/figures/_book_figs.R")

suppressPackageStartupMessages({
  library(ggplot2)
})

assert_book_font()

# ---- Figure 2.1: observational study versus randomized experiment ----------

# Boxes are defined by their edges so arrows can stop at the border. Panel A
# occupies y = 56 to 100, panel B y = 0 to 50, with a divider at y = 50.
boxes <- data.frame(
  xmin = c(4, 40, 72, 4, 34, 64),
  xmax = c(30, 64, 98, 24, 54, 88),
  ymin = c(71, 72, 69, 17, 17, 18),
  ymax = c(85, 84, 87, 31, 31, 30),
  fill = c(
    "#DCE9F5", "#FFFFFF", "#FBE3D6",
    "#DCE9F5", "#DCE9F5", "#FFFFFF"
  ),
  label = c(
    "Perceived race\n(applicant name)",
    "Interview\ncallback",
    "Hidden differences:\nexperience, role type,\nuniversity rank",
    "Random\nassignment",
    "Name\n(perceived race)",
    "Interview\ncallback"
  ),
  stringsAsFactors = FALSE
)

# Direct effects within each panel. Panel B has no confounder path because
# random assignment and identical resumes remove it.
arrows <- data.frame(
  x = c(30, 72, 24, 54),
  y = c(78, 78, 24, 24),
  xend = c(39.5, 64.5, 33.5, 63.5),
  yend = c(78, 78, 24, 24)
)

p21 <- ggplot() +
  annotate(
    "segment", x = 2, xend = 98, y = 50, yend = 50,
    colour = BOOK_GRID, linewidth = 0.5
  ) +
  annotate(
    "text", x = 4, y = 96, label = "A. Observational study",
    hjust = 0, size = 4.0, fontface = "bold", colour = BOOK_INK
  ) +
  annotate(
    "text", x = 4, y = 43, label = "B. Randomized experiment",
    hjust = 0, size = 4.0, fontface = "bold", colour = BOOK_INK
  ) +
  geom_segment(
    data = arrows,
    aes(x = x, y = y, xend = xend, yend = yend),
    colour = BOOK_INK, linewidth = 0.5,
    arrow = arrow(length = unit(0.16, "cm"), type = "closed")
  ) +
  # Confounding path in the observational panel: hidden differences feed both
  # the perceived race and the callback, so the race-to-callback arrow alone
  # cannot carry a causal claim.
  annotate(
    "segment", x = 85, xend = 85, y = 69, yend = 64,
    colour = BOOK_INK, linewidth = 0.5
  ) +
  annotate(
    "segment", x = 85, xend = 17, y = 64, yend = 64,
    colour = BOOK_INK, linewidth = 0.5
  ) +
  annotate(
    "segment", x = 17, xend = 17, y = 64, yend = 70.5,
    colour = BOOK_INK, linewidth = 0.5,
    arrow = arrow(length = unit(0.16, "cm"), type = "closed")
  ) +
  geom_rect(
    data = boxes,
    aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax),
    fill = boxes$fill, colour = BOOK_INK, linewidth = 0.45
  ) +
  geom_text(
    data = boxes,
    aes(x = (xmin + xmax) / 2, y = (ymin + ymax) / 2, label = label),
    size = 3.3, lineheight = 0.95, colour = BOOK_INK
  ) +
  annotate(
    "text", x = 52, y = 58.5,
    label = "Hidden differences can affect both the name and the callback.",
    size = 3.0, colour = BOOK_INK, fontface = "italic"
  ) +
  annotate(
    "text", x = 46, y = 8,
    label = "Identical resumes hold experience, jobs, and education constant.",
    size = 3.0, colour = BOOK_INK, fontface = "italic"
  ) +
  coord_cartesian(xlim = c(0, 100), ylim = c(0, 100), clip = "off") +
  theme_void(base_family = BOOK_FONT) +
  theme(
    plot.background = element_rect(fill = BOOK_BG, colour = NA),
    plot.margin = margin(10, 12, 10, 12)
  )

save_book_fig(
  p21,
  chapter = 2, id = "2.1", type = "diagram",
  slug = "observational_vs_experiment",
  caption = paste(
    "Observational data compared with a randomized experiment. In the",
    "observational panel, hidden differences such as experience and",
    "university rank can affect both perceived race and interview callbacks.",
    "In the experiment, random assignment and identical resumes remove those",
    "paths."
  ),
  alt = paste(
    "Two-panel diagram comparing study designs. In the observational panel,",
    "hidden differences such as experience and university rank affect both",
    "perceived race and interview callbacks. In the experiment panel, random",
    "assignment sets the name and identical resumes hold qualifications",
    "constant."
  ),
  width = 6.5, height = 5.5,
  direct_labels = TRUE
)
